args.query:
\d api.application
\d api.company
\d api.app_user
select * from api.app_user;
select relname, relrowsecurity, relforcerowsecurity, relowner::regrole from pg_class where relnamespace='api'::regnamespace;
select * from pg_policies;
select grantee, table_name, privilege_type from information_schema.role_table_grants where table_schema='api' order by 2,1;
select rolname from pg_roles where rolname !~ '^pg_';
select proname, prosecdef from pg_proc where pronamespace='api'::regnamespace;
select tgname, tgrelid::regclass from pg_trigger where not tgisinternal;

select * from api.status;
select p.oid::regprocedure, prosecdef, pg_get_functiondef(p.oid) from pg_proc p where pronamespace='priv'::regnamespace;
select r.rolname, m.rolname from pg_auth_members am join pg_roles r on r.oid=roleid join pg_roles m on m.oid=member;
select id,number,company_id,status_id,amount from api.application order by id;
select * from api.company;

begin;
create table api.contract(
 id integer generated always as identity primary key,
 number text not null unique,
 application_id integer not null references api.application(id),
 amount numeric not null check (amount>0),
 signed_on date not null default current_date,
 status text not null default 'Проект' check (status in ('Проект','Подписан')));
create index on api.contract(application_id);
create function priv.check_contract() returns trigger language plpgsql security definer set search_path to 'api' as $$
begin
 if not exists (select 1 from api.application a join api.status s on s.id=a.status_id where a.id=NEW.application_id and s.name='Одобрена') then
  raise exception 'договор можно заключить только по одобренной заявке' using errcode='check_violation';
 end if;
 return NEW;
end $$;
create trigger check_contract before insert or update on api.contract for each row execute function priv.check_contract();
alter table api.contract enable row level security;
grant select,insert,update,delete on api.contract to fund_admin;
grant select,insert,update on api.contract to lawyer;
grant select on api.contract to applicant;
create policy admin_all on api.contract for all to fund_admin using(true) with check(true);
create policy lawyer_read on api.contract for select to lawyer using(true);
create policy lawyer_insert on api.contract for insert to lawyer with check(true);
create policy lawyer_update on api.contract for update to lawyer using(true) with check(true);
create policy applicant_read on api.contract for select to applicant using (exists (select 1 from api.application a where a.id=application_id and a.company_id=priv.my_company()));
grant select on api.application, api.company, api.status to lawyer;
create policy lawyer_read on api.application for select to lawyer using(true);
grant usage on schema priv to lawyer;
create view api.limit_balance with (security_invoker=true) as
select c.name as company, c.funding_limit, ap.approved, coalesce(ct.contracted,0) as contracted, c.funding_limit-coalesce(ct.contracted,0) as remaining
from api.company c
join (select a.company_id, sum(a.amount) approved from api.application a join api.status s on s.id=a.status_id where s.name='Одобрена' group by 1) ap on ap.company_id=c.id
left join (select a.company_id, sum(k.amount) contracted from api.contract k join api.application a on a.id=k.application_id group by 1) ct on ct.company_id=c.id;
grant select on api.limit_balance to fund_admin, lawyer, applicant;
update api.app_user set role='lawyer' where login='lawyer1';
commit;
\dp priv.*
select nspname, has_schema_privilege('applicant',oid,'usage') from pg_namespace where nspname='priv';
